<script setup lang="ts">
import ActionMenu from "../../components/ActionMenu.vue";
import {Head,Link,router,useForm} from '@inertiajs/vue3';
import {computed} from 'vue';
import ConfirmDialog from '../../components/ConfirmDialog.vue';
import AppLayout from '../../layouts/AppLayout.vue';
import {rupiah as money} from '../../composables/costing';
import {progress,type OpsProgram,type Budget,type ExpenseRow} from '../../types/operations';
const props=defineProps<{program:OpsProgram;category:string;budget:Budget;headers:Record<string,ExpenseRow[]>;canAdd:boolean;notTeam:boolean;lastAccount:{bank:string;no_rekening:string;nama_rekening:string}|null;creating:string|null;requestBy:string;today:string}>();
const over=props.creating==='overbudget';
const form=useForm({tipe_biaya:props.category,jenis:'kasbon',deskripsi:'',alasan:'',bank:props.lastAccount?.bank || '',no_rekening:props.lastAccount?.no_rekening || '',nama_rekening:props.lastAccount?.nama_rekening || '',bukti:[] as File[],items:props.budget.items.filter(i=>!over || i.id_penjualan_biaya).map(i=>({key:i.key,item:i.item,qty:'0',harga:i.harga}))});
function price(event:Event,item:{harga:string}){const el=event.target as HTMLInputElement;const value=el.value.replace(/\./g,'');if(/^\d{0,13}$/.test(value))item.harga=value;el.value=Number(item.harga).toLocaleString('id-ID',{maximumFractionDigits:0});}
const total=computed(()=>form.items.reduce((n,i)=>n+Math.round(Number(i.qty)*Number(i.harga)*100)/100,0));
const submit=()=>form.post(`/pengajuan-biaya/program/${props.program.id}/${props.creating}`,{forceFormData:true});
const exceeded=(i:{key:string;qty:string;harga:string})=>Number(i.qty)*Number(i.harga)>Number(props.budget.items.find(b=>b.key===i.key)?.sisa || 0);
</script>
<template><Head :title="program.nomor"/><AppLayout title="Pengajuan Biaya"><div class="page-head"><h1>{{program.nomor}} · {{creating?(over?'Add Overbudget':'Add Pengajuan'):'Pengajuan Biaya'}}</h1><Link :href="creating?`/pengajuan-biaya/program/${program.id}?kategori=${category}`:'/pengajuan-biaya'">Kembali</Link></div><section class="panel"><h2>{{program.judul}}</h2><p>{{program.jenis.toUpperCase()}} · {{program.tim?.company}} · {{program.tgl_mulai}} s.d. {{program.tgl_selesai}} · {{program.durasi_hari}} hari · {{program.lokasi}}</p><p>Sales {{program.tim?.sales.join(', ')}} · Trainer {{program.tim?.trainer}} · Target {{program.target_peserta}} peserta.</p><p v-if="program.closed_date" class="notice">Program Closed; pengajuan baru terkunci. Pengajuan existing tetap dapat diselesaikan.</p><p v-if="creating">Request By {{requestBy}} ? Tanggal {{today}}</p><p v-if="notTeam" class="notice">Anda bukan tim program ini. Akses mengikuti role dan izin yang diberikan.</p></section><nav v-if="!creating" class="tabs" aria-label="Kategori biaya"><Link :href="`/pengajuan-biaya/program/${program.id}?kategori=fixed`" :aria-current="category==='fixed'?'page':undefined">Fixed Cost</Link><Link :href="`/pengajuan-biaya/program/${program.id}?kategori=variable`" :aria-current="category==='variable'?'page':undefined">Variable Cost</Link></nav><section class="panel"><h2>{{category==='fixed'?'Fixed Cost':'Variable Cost'}}</h2><div class="kpis budget-summary"><div class="kpi"><span class="kpi-l">Budget</span><strong class="kpi-v">{{money(budget.budget)}}</strong></div><div class="kpi"><span class="kpi-l">Aktual</span><strong class="kpi-v">{{money(budget.aktual)}}</strong></div><div class="kpi" :class="Number(budget.sisa)<=0?'bad':'good'"><span class="kpi-l">Sisa Budget</span><strong class="kpi-v">{{money(budget.sisa)}}</strong></div></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>Estimasi Qty × Harga</th><th>Total Budget</th><th>Overbudget Qty / Total</th><th>Terpakai Qty / Total</th><th>Sisa item</th></tr></thead><tbody><tr v-for="i in budget.items" :key="i.key"><td>{{i.item}}<small v-if="!i.id_penjualan_biaya">Item baru</small></td><td>{{i.qty}} × {{money(i.harga)}}</td><td>{{money(i.budget)}}</td><td>{{i.qty_overbudget}} / {{money(i.overbudget)}}</td><td>{{i.qty_terpakai}} / {{money(i.terpakai)}}</td><td>{{money(i.sisa)}}</td></tr></tbody></table></div></section>
<template v-if="!creating"><div v-for="(list,table) in headers" :key="table" class="panel"><div class="page-head"><h2>{{table==='pengajuan_biaya'?'Pengajuan':'Overbudget'}}</h2><Link v-if="canAdd" :href="`/pengajuan-biaya/program/${program.id}?kategori=${category}&buat=${table==='pengajuan_biaya'?'pengajuan':'overbudget'}`">+ Add {{table==='pengajuan_biaya'?'Pengajuan':'Overbudget'}}</Link></div><div class="table-wrap"><table><thead><tr><th>Nomor</th><th>Deskripsi</th><th>Total</th><th>Request By</th><th>Progres</th><th>Aksi</th></tr></thead><tbody><tr v-for="h in list" :key="h.id"><td>{{h.nomor}}<small>{{h.tanggal}}</small></td><td>{{h.deskripsi || h.alasan}}</td><td>{{money(h.total)}}</td><td>{{h.pengaju}}</td><td>{{table==='pengajuan_biaya'?progress[h.status]:h.status}}</td><td><ActionMenu><Link :href="`/pengajuan-biaya/${table==='pengajuan_biaya'?'pengajuan':'overbudget'}/${h.id}`">Lihat</Link></ActionMenu></td></tr><tr v-if="!list.length"><td colspan="6" class="empty">Belum ada pengajuan.</td></tr></tbody></table></div></div></template>
<component v-else :is="over?ConfirmDialog:'section'" title="Add Overbudget" :busy="form.processing" @confirm="submit" @cancel="router.get(`/pengajuan-biaya/program/${program.id}`,{kategori:category})"><form class="panel stack" @submit.prevent="submit"><h2>{{over?'Add Overbudget':'Add Pengajuan'}} · {{category==='fixed'?'Fixed Cost':'Variable Cost'}}</h2><label v-if="over">Alasan wajib<textarea v-model="form.alasan" maxlength="2000" required/></label><template v-else><label>Jenis<select v-model="form.jenis" required @change="form.jenis==='direct_payment' && (form.bank='',form.no_rekening='',form.nama_rekening='')"><option value="kasbon">Kasbon</option><option value="direct_payment">Direct Payment</option></select></label><label>Deskripsi / keterangan<textarea v-model="form.deskripsi" maxlength="2000" required/></label></template><div class="table-wrap"><table><thead><tr><th>Item</th><th>Qty</th><th>Price/Unit (Rp)</th><th>Total pengajuan</th><th v-if="over">Aksi</th></tr></thead><tbody><tr v-for="(i,n) in form.items" :key="n"><td><input v-if="over && !i.key" v-model="i.item" :aria-label="`Nama item baru ${n+1}`" maxlength="150" required/><template v-else>{{i.item}}</template><small v-if="!over && exceeded(i)">Melebihi sisa item; diperbolehkan selama kategori cukup.</small></td><td><input v-model="i.qty" :aria-label="`Qty ${i.item || n+1}`" type="number" min="0" max="99999999.99" step="0.01" :disabled="!over && Number(budget.sisa)<=0" required/></td><td><input :value="Number(i.harga).toLocaleString('id-ID',{maximumFractionDigits:0})" :aria-label="`Harga ${i.item || n+1}`" type="text" inputmode="numeric" maxlength="17" pattern="[0-9.]+" @input="price($event,i)" :disabled="!over && Number(budget.sisa)<=0" required/></td><td>{{money(Number(i.qty)*Number(i.harga))}}</td><td v-if="over"><button type="button" @click="form.items.splice(n,1)">Hapus</button></td></tr></tbody></table></div><button v-if="over" type="button" @click="form.items.push({key:'',item:'',qty:'1',harga:'0'})">+ Item baru</button><p>Grand Total {{money(Math.round(total))}}<template v-if="!over"> · Sisa kategori setelah pengajuan {{money(Math.round(Number(budget.sisa)-total))}}</template></p><template v-if="!over"><h3>{{form.jenis==='kasbon'?'Rekening pengaju':'Rekening penerima / vendor'}}</h3><div class="form-grid"><label>Bank<input v-model="form.bank" maxlength="50" required/></label><label>No. Rekening<input v-model="form.no_rekening" maxlength="30" required/></label><label>Nama Rekening<input v-model="form.nama_rekening" maxlength="100" required/></label></div><label>Bukti PDF/JPG/PNG maksimal 5 MB per file {{form.jenis==='direct_payment'?'(wajib)':'(opsional)'}}<input type="file" multiple accept=".pdf,.jpg,.jpeg,.png" :required="form.jenis==='direct_payment'" @change="form.bukti=Array.from(($event.target as HTMLInputElement).files || [])"/></label></template><p>Perhitungan akhir dan batas budget diverifikasi server. Pengajuan langsung Waiting Approval; koreksi melalui batal lalu ajukan ulang.</p><p v-for="e in form.errors" :key="e" class="error" role="alert">{{e}}</p><button v-if="!over" class="primary" :disabled="form.processing || (!over && Number(budget.sisa)<=0)">Save</button></form></component></AppLayout></template>
